staging/src/k8s.io/client-go/tools/remotecommand/errorstream.go L35-54 @ 42c4ddbe2d
OBSERVATION: The function watchErrorStream in errorstream.go at lines 35-54 transforms the upstream error from io.ReadAll into a formatted string using fmt.Errorf with a %s verb. This results in losing the original error type and wraps it as a plain formatted string error. This makes it impossible for callers to use errors.Is or errors.As on the underlying error, thus explaining the reported bug.
func watchErrorStream(errorStream io.Reader, d errorStreamDecoder) chan error {
	errorChan := make(chan error)

	go func() {
		defer runtime.HandleCrash()

		message, err := io.ReadAll(errorStream)
		switch {
		case err != nil && err != io.EOF:
			errorChan <- fmt.Errorf("error reading from error stream: %s", err)
		case len(message) > 0:
			errorChan <- d.decode(message)
		default:
			errorChan <- nil
		}
		close(errorChan)
	}()

	return errorChan
}

