staging/src/k8s.io/apiserver/pkg/cel/library/cidr.go L221-234 @ 4205f04ce3
OBSERVATION: The function cidrContainsCIDR, which implements the containsCIDR check in CEL, attempts to compare the masked prefix of the first CIDR to a newly constructed prefix. However, it uses cidr.Prefix.Bits() as the mask bits for the second prefix, which is incorrect. It should use containsCIDR.Prefix.Bits() instead since the intention is to check if the first CIDR contains the second. This mistake in prefix masking logic causes the containment check to behave incorrectly, leading to the validation failure described in the ticket.
func cidrContainsCIDR(arg ref.Val, other ref.Val) ref.Val {
	cidr, ok := arg.(apiservercel.CIDR)
	if !ok {
		return types.MaybeNoSuchOverloadErr(arg)
	}

	containsCIDR, ok := other.(apiservercel.CIDR)
	if !ok {
		return types.MaybeNoSuchOverloadErr(other)
	}

	equalMasked := cidr.Prefix.Masked() == netip.PrefixFrom(containsCIDR.Prefix.Addr(), cidr.Prefix.Bits())
	return types.Bool(equalMasked && cidr.Prefix.Bits() <= containsCIDR.Prefix.Bits())
}

